function limpiarTelefono(numero) {
  if (!numero) return '';

  let limpio = numero.toString().replace(/\D/g, '');

  if (limpio.startsWith('521') && limpio.length === 13) {
    return limpio.slice(3);
  }

  if (limpio.startsWith('52') && limpio.length === 12) {
    return limpio.slice(2);
  }

  return limpio.slice(-10);
}

const mensaje = $json.messages?.[0];

let texto = '';
let numero = '';

if (mensaje?.text?.body) {
  texto = mensaje.text.body;
}

if (mensaje?.from) {
  numero = limpiarTelefono(mensaje.from);
}

return {
  json: {
    numero: numero,
    texto: (texto || '').trim()
  }
};

const grupoInput = ($json.Grupo || '').toLowerCase().trim();

const filas = items.map(item => item.json);

// 🔴 SI NO HAY FILAS → grupo no existe
if (filas.length === 0) {
  return [
    {
      json: {
        ...$json,
        grupo_valido: false
      }
    }
  ];
}

// buscar coincidencia
const grupoEncontrado = filas.find(fila => 
  (fila.Grupo || '').toLowerCase().trim() === grupoInput
);

const grupoExiste = !!grupoEncontrado;

return [
  {
    json: {
      ...$json,
      grupo_valido: grupoExiste
    }
  }
];

function normalizarGrupo(texto) {
  if (!texto) return '';

  let limpio = texto
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "")
    .replace(/[^a-z0-9]/g, "");

  const match = limpio.match(/\d+/);
  if (!match) return '';

  let numero = match[0].padStart(3, '0');

  return `GSS${numero}`;
}

const grupoNormalizado = normalizarGrupo(
  $node["Extraer mensaje"].json.texto
);

return [
  {
    json: {
      ...$json,
      grupo_input_normalizado: grupoNormalizado
    }
  }
];

function generarID() {
  const random = Math.random().toString(36).substring(2, 8);
  const timestamp = Date.now().toString(36);
  return `USR-${timestamp}-${random}`;
}

return [
  {
    json: {
      ...$json,
      ID: generarID()
    }
  }
];

function normalizarTelefono(numero) {
  if (!numero) return '';

  // dejar solo números
  let limpio = numero.toString().replace(/\D/g, '');

  // si viene como 521XXXXXXXXXX → quitar 521
  if (limpio.startsWith('521') && limpio.length === 13) {
    return limpio.slice(3);
  }

  // si viene como 52XXXXXXXXXX → quitar 52
  if (limpio.startsWith('52') && limpio.length === 12) {
    return limpio.slice(2);
  }

  // si ya viene como 10 dígitos → dejarlo
  if (limpio.length === 10) {
    return limpio;
  }

  // fallback: devolver últimos 10 dígitos
  return limpio.slice(-10);
}

return [
  {
    json: {
      ...$json,
      telefono_normalizado: normalizarTelefono(
        $item(0).$node["Extraer mensaje"].json.numero
      )
    }
  }
];
